1	// Validate a trace corpus BEFORE using it: chaining, terminal states, no-op
2	// windows, and a (pre-state x action) coverage table with a warning for any
3	// special rule under-covered. The corpus is ground truth — this catches capture
4	// bugs, not modeling bugs.
5	//
6	// Usage: node validate_corpus.mjs <contract.json> <traces-dir-or-file>
7	import { readFileSync, readdirSync } from 'node:fs';
8	import { join } from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	import { stable } from './load-spec.mjs';
11	
12	// Canonical (key-order-insensitive) equality — the same definition the
13	// replayers and checker use. Raw JSON.stringify would report a false "chain
14	// break" whenever a capturer emits post and the next pre with different key
15	// order.
16	const eq = (a, b) => stable(a) === stable(b);
17	
18	/** The primary state field = the first declared key (the control state). */
19	function stateField(contract) {
20	  const k = contract.stateKeys[0];
21	  return typeof k === 'string' ? k : k.name;
22	}
23	
24	/**
25	 * specialRules declare `whenState`/`whenAction` as the SHORT EXPRESSIONS the
26	 * contract convention uses — `orderState == 'charging'`, `shipState !=
27	 * 'preparing'`, `subState in ('canceled','unpaid')`, `A | B | C` — not as bare
28	 * literals. Comparing them to a state value with `===` (as this tally did
29	 * until 2026-07) can never match, so every polygen-shaped contract reported
30	 * 0 windows for every rule and warned about it forever. Found while capturing
31	 * the fleet-study corpus: the repo's OWN demo corpus, which contains traces
32	 * named `cancel_blocked_while_charging_*`, scored 0 for that rule.
33	 *
34	 * These matchers parse the three structured forms and report anything else as
35	 * unparseable rather than silently counting it as a miss.
36	 */
37	function matchState(expr, preState) {
38	  if (!expr) return true;
39	  const e = expr.trim();
40	  const lits = (s) => [...s.matchAll(/'([^']*)'/g)].map((m) => m[1]);
41	  // Two conventions ship in this repo, and both are legitimate:
42	  //   bare literal — "LOCKED"                     (the turnstile examples)
43	  //   expression   — "orderState == 'charging'"   (polygen-authored contracts)
44	  // Anything else is prose ("any non-awaiting state") and is unmeasurable.
45	  if (!/[=!]|\bin\s*\(/.test(e)) return /\s/.test(e) ? null : e === preState;
46	  const inMatch = /\bin\s*\(([^)]*)\)/.exec(e);
47	  if (inMatch) {
48	    const set = lits(inMatch[1]);
49	    return /!\s*in|\bnot\s+in/.test(e) ? !set.includes(preState) : set.includes(preState);
50	  }
51	  if (/!==?/.test(e)) return !lits(e).includes(preState);
52	  if (/==?/.test(e)) return lits(e).includes(preState);
53	  return null;
54	}
55	
56	function matchAction(expr, action) {
57	  if (!expr) return true;
58	  return expr.split('|').map((s) => s.trim()).filter(Boolean).includes(action);
59	}
60	
61	export function validateCorpus(contract, tracePath) {
62	  const sf = stateField(contract);
63	  const terminals = new Set(contract.terminalStates || []);
64	  const declaredActions = new Set(Object.keys(contract.actions || {}));
65	  const ruleWindows = {}; // ruleName -> count of windows matching its declared (state, action)
66	  for (const r of contract.specialRules || []) ruleWindows[r.name] = 0;
67	  // Rules whose whenState is prose rather than an expression: counted as
68	  // UNMEASURABLE rather than as zero, so a documentation choice never reads
69	  // as missing coverage.
70	  const unparseableRules = new Set();
71	
72	  const problems = [];
73	  const coverage = {}; // `${pre}|${action}` -> count
74	  const seenKeys = new Set(); // declared state keys observed anywhere in the corpus
75	  let total = 0, noops = 0;
76	
77	  let files;
78	  try {
79	    files = readdirSync(tracePath).filter((f) => f.endsWith('.ndjson')).sort().map((f) => join(tracePath, f));
80	  } catch {
81	    files = [tracePath];
82	  }
83	
84	  for (const f of files) {
85	    const scenario = f.replace(/^.*[\\/]/, '');
86	    const windows = readFileSync(f, 'utf-8').split('\n').filter((l) => l.trim()).map((l) => JSON.parse(l));
87	    windows.forEach((w, i) => {
88	      total++;
89	      // Window shape first: a malformed window must be a REPORTED problem,
90	      // not a crash — and a window with an empty post would replay vacuously.
91	      const isObj = (o) => o !== null && typeof o === 'object' && !Array.isArray(o);
92	      if (!isObj(w.pre) || !isObj(w.post) || typeof w.action !== 'string') {
93	        problems.push(`${scenario}[${i}]: malformed window — pre/post must be objects and action a string`);
94	        return;
95	      }
96	      if (Object.keys(w.post).length === 0) {
97	        problems.push(`${scenario}[${i}]: post is EMPTY — the window would replay vacuously (projection over zero keys)`);
98	      }
99	      // The PRIMARY state field (control state) must be present in every
100	      // window — a capture bug that renames it poisons every downstream
101	      // comparison. Other declared keys may legitimately be absent per
102	      // window (SAM getState() omits undefined-valued keys); they are
103	      // checked corpus-wide below instead.
104	      if (!(sf in w.pre)) problems.push(`${scenario}[${i}]: pre is missing declared state key '${sf}'`);
105	      if (!(sf in w.post)) problems.push(`${scenario}[${i}]: post is missing declared state key '${sf}'`);
106	      for (const k of contract.stateKeys || []) {
107	        const keyName = typeof k === 'string' ? k : k.name;
108	        if (keyName in w.pre || keyName in w.post) seenKeys.add(keyName);
109	      }
110	      const pre = w.pre[sf];
111	      const key = `${pre}|${w.action}`;
112	      coverage[key] = (coverage[key] || 0) + 1;
113	
114	      // undeclared action: an ERROR, not a warning. The v2 strict pipeline
115	      // cannot no-op an action outside the contract alphabet (schemas and
116	      // acceptors are keyed by name), so a corpus that exercises one is a
117	      // contract gap that must be fixed at the contract, not absorbed.
118	      if (!declaredActions.has(w.action)) {
119	        problems.push(`${scenario}[${i}]: action '${w.action}' is not declared in the contract's actions`);
120	      }
121	
122	      // chaining: post[k] == pre[k+1]
123	      if (i + 1 < windows.length && !eq(w.post, windows[i + 1].pre)) {
124	        problems.push(`${scenario}[${i}]: post != next pre (chain break)`);
125	      }
126	      // no-op detection (pre == post): count it
127	      if (eq(w.pre, w.post)) noops++;
128	
129	      // special-rule tally (a rule "matches" a window if its declared pre-state
130	      // and action are present; declared as { name, note, whenState?, whenAction? })
131	      for (const r of contract.specialRules || []) {
132	        const stateOk = matchState(r.whenState, pre);
133	        if (stateOk === null) { unparseableRules.add(r.name); continue; }
134	        if (stateOk && matchAction(r.whenAction, w.action)) ruleWindows[r.name]++;
135	      }
136	    });
137	
138	    // terminal expectation: scenario's last post primary state should be terminal
139	    if (windows.length && terminals.size) {
140	      const lastState = windows[windows.length - 1].post[sf];
141	      if (!terminals.has(lastState)) {
142	        problems.push(`${scenario}: ends in '${lastState}', not a declared terminal state`);
143	      }
144	    }
145	  }
146	
147	  // A zero-window corpus can't be ground truth for anything — validating it
148	  // "clean" would be a silent-clean path. Make it a hard problem.
149	  if (files.length === 0) problems.push(`no .ndjson files found in ${tracePath}`);
150	  else if (total === 0) problems.push(`corpus contains zero windows (all files empty)`);
151	
152	  // A declared key that never appears in ANY window was renamed or dropped by
153	  // the capture projection (per-window absence is legitimate — getState()
154	  // omits undefined-valued keys — corpus-wide absence is not).
155	  if (total > 0) {
156	    for (const k of contract.stateKeys || []) {
157	      const keyName = typeof k === 'string' ? k : k.name;
158	      if (!seenKeys.has(keyName)) problems.push(`declared state key '${keyName}' never appears in any window (renamed or dropped by the capture projection?)`);
159	    }
160	  }
161	
162	  // A rule whose whenState is prose cannot be tallied mechanically, so it is
163	  // never counted as under-covered — that would be reporting a documentation
164	  // style as missing test coverage.
165	  const underCovered = Object.entries(ruleWindows)
166	    .filter(([n, c]) => c < 3 && !unparseableRules.has(n))
167	    .map(([n, c]) => ({ rule: n, windows: c }));
168	
169	  return { total, noops, coverage, ruleWindows, underCovered, problems, unmeasurableRules: [...unparseableRules] };
170	}
171	
172	function printReport(rep) {
173	  console.log(`Windows: ${rep.total} (${rep.noops} no-op)`);
174	  console.log('\nCoverage (pre-state x action):');
175	  const rows = Object.entries(rep.coverage).sort();
176	  const w = Math.max(...rows.map(([k]) => k.length), 8);
177	  for (const [k, c] of rows) console.log(`  ${k.padEnd(w)}  ${c}`);
178	  if (Object.keys(rep.ruleWindows).length) {
179	    console.log('\nSpecial-rule coverage:');
180	    const unmeasurable = new Set(rep.unmeasurableRules ?? []);
181	    for (const [n, c] of Object.entries(rep.ruleWindows)) {
182	      const note = unmeasurable.has(n)
183	        ? '  <-- not mechanically measurable (whenState is prose, not an expression)'
184	        : (c < 3 ? '  <-- WARNING: <3 windows' : '');
185	      console.log(`  ${n.padEnd(w)}  ${unmeasurable.has(n) ? '—' : c}${note}`);
186	    }
187	  }
188	  if (rep.problems.length) {
189	    console.log('\nProblems:');
190	    for (const p of rep.problems) console.log(`  ! ${p}`);
191	  } else {
192	    console.log('\nNo chaining/terminal problems found.');
193	  }
194	}
195	
196	// CLI
197	if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
198	  const [, , contractPath, tracePath] = process.argv;
199	  if (!contractPath || !tracePath) {
200	    console.error('usage: node validate_corpus.mjs <contract.json> <traces-dir-or-file>');
201	    process.exit(2);
202	  }
203	  const contract = JSON.parse(readFileSync(contractPath, 'utf-8'));
204	  const rep = validateCorpus(contract, tracePath);
205	  printReport(rep);
206	  // Under-covered special rules are a warning, not a hard failure; chain/terminal
207	  // breaks are a hard failure (the corpus is not trustworthy).
208	  process.exit(rep.problems.length ? 1 : 0);
209	}
