// The rules the brief requires, as predicates over spec/checkout.cjs states.
const STOCK = 2;
const LIMIT = 4;

const parse = (m) => {
  const [route, action, n] = m.split(':');
  const [from, to] = route.split('>');
  return { from, to, action, n: Number(n) };
};
const msgs = (s) => s.net.map(parse);
const carts = (s) => Object.entries(s.carts);
const sum = (xs) => xs.reduce((a, b) => a + b, 0);
const inFlight = (s, pred) => msgs(s).some(pred);

const paidUnits = (s) => sum(carts(s).filter(([, c]) => c.status === 'paid').map(([, c]) => c.items));

// Units the inventory holds for a cart right now (reserved, not yet released).
const heldBy = (s, id, c) => {
  if (c.status === 'paying' || c.status === 'paid') return c.items;
  if ((c.status === 'reserving' || c.status === 'cancelling') &&
      inFlight(s, (m) => m.to === id && m.action === 'Reserved')) return c.items;
  return 0;
};
const releasing = (s) => sum(msgs(s).filter((m) => m.action === 'Release').map((m) => m.n));

export const stateInvariants = [
  { name: 'stock-conserved', pred: (s) => s.available >= 0 && s.reserved >= 0 && s.available + s.reserved === STOCK },
  { name: 'reserved-accounted', pred: (s) => s.reserved === sum(carts(s).map(([id, c]) => heldBy(s, id, c))) + releasing(s) },
  {
    name: 'charged-accounted',
    pred: (s) => s.charged === paidUnits(s) + sum(carts(s)
      .filter(([id, c]) => c.status === 'paying' && inFlight(s, (m) => m.to === id && m.action === 'Charged'))
      .map(([, c]) => c.items)),
  },
  { name: 'quiescent-reserved-is-paid', pred: (s) => s.net.length > 0 || s.reserved === paidUnits(s) },
  { name: 'quiescent-charged-is-paid', pred: (s) => s.net.length > 0 || s.charged === paidUnits(s) },
  { name: 'charge-limit', pred: (s) => s.charged <= LIMIT },
  { name: 'items-bounded', pred: (s) => carts(s).every(([, c]) => c.items >= 0 && c.items <= 2) },
  { name: 'checked-out-carts-nonempty', pred: (s) => carts(s).every(([, c]) => ['none', 'open', 'cancelled'].includes(c.status) || c.items >= 1) },
  { name: 'one-message-per-cart', pred: (s) => carts(s).every(([id]) => msgs(s).filter((m) => m.from === id || m.to === id).length <= 1) },
];

const cartIds = (s) => Object.keys(s.carts);
const delivered = (pre, data) => (data && typeof data.i === 'number' ? parse(pre.net[data.i] ?? '?>?:?:0') : null);

export const transitionInvariants = [
  {
    name: 'paid-only-after-reserve-and-charge',
    pred: (pre, action, data, post) => cartIds(post).every((id) => {
      if (post.carts[id].status !== 'paid' || pre.carts[id].status === 'paid') return true;
      const m = delivered(pre, data);
      return action === 'DELIVER' && pre.carts[id].status === 'paying' && m.to === id && m.action === 'Charged';
    }),
  },
  {
    name: 'paying-only-after-reserved',
    pred: (pre, action, data, post) => cartIds(post).every((id) => {
      if (post.carts[id].status !== 'paying' || pre.carts[id].status === 'paying') return true;
      const m = delivered(pre, data);
      return action === 'DELIVER' && pre.carts[id].status === 'reserving' && m.to === id && m.action === 'Reserved';
    }),
  },
  {
    name: 'failed-or-cancelled-gives-back',
    pred: (pre, action, data, post) => cartIds(post).every((id) => {
      const before = pre.carts[id], after = post.carts[id];
      if (before.status === after.status || !['failed', 'cancelled'].includes(after.status)) return true;
      const held = heldBy(pre, id, before);
      const m = delivered(pre, data);
      const justReserved = m && m.to === id && m.action === 'Reserved' ? before.items : 0;
      const owed = held || justReserved;
      const releases = post.net.map(parse).filter((x) => x.from === id && x.action === 'Release');
      return owed === 0 ? releases.length === 0 : releases.length === 1 && releases[0].n === owed;
    }),
  },
  { name: 'paid-is-final', pred: (pre, _a, _d, post) => cartIds(pre).every((id) => pre.carts[id].status !== 'paid' || post.carts[id].status === 'paid') },
  { name: 'charged-never-decreases', pred: (pre, _a, _d, post) => post.charged >= pre.charged },
  {
    name: 'carts-change-only-by-their-own-command-or-message',
    pred: (pre, action, data, post) => cartIds(post).every((id) => {
      if (JSON.stringify(pre.carts[id]) === JSON.stringify(post.carts[id])) return true;
      if (action === 'DELIVER') return delivered(pre, data).to === id;
      return data && data.cart === id;
    }),
  },
];

