test('return a paid cart: refund and release', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.returnCart('zz')).ok, false);
  await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.returnCart('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 2 });
  const msgs = (await h.inFlight()).map(({ from, to, action, data }) => ({ from, to, action, data }));
  assert.deepEqual(msgs.sort((x, y) => x.to.localeCompare(y.to)), [
    { from: 'a', to: 'inventory', action: 'Release', data: { qty: 2 } },
    { from: 'a', to: 'payments', action: 'Refund', data: { amount: 2 } },
  ]);
  for (const c of ['add', 'checkout', 'cancel', 'returnCart'] as const) assert.equal((await h[c]('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.inFlight(), []);
});

test('charge limit reachable while refunds are in transit', async () => {
  const h = await createHost();
  const buy = async (c: string) => { await h.open(c); await h.add(c); await h.add(c); await h.checkout(c); await h.deliverAll(); };
  const returnKeepingRefund = async (c: string) => {
    await h.returnCart(c);
    for (const m of await h.inFlight()) if (m.action === 'Release') await h.deliver(m.id);
  };
  await buy('a'); await returnKeepingRefund('a');
  await buy('b'); await returnKeepingRefund('b');
  assert.equal((await h.payments()).charged, 4);
  await buy('c');
  assert.equal((await h.cart('c'))!.status, 'failed');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  await h.deliverAll();
  assert.equal((await h.payments()).charged, 0);
});

