// Negative control: hand-made mutants of spec/checkout.cjs must be caught by the
// invariants (model check). Run: node spec/negative-control.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { check, loadSpec } from '../tools/polygraph/scripts/check.mjs';
import * as invariants from './invariants.mjs';

const contract = JSON.parse(readFileSync(new URL('./contract.json', import.meta.url), 'utf-8'));
const source = readFileSync(new URL('./checkout.cjs', import.meta.url), 'utf-8');

const MUTANTS = {
  'decline-keeps-reservation': [
    "status = 'failed';\n            net = withSent(rest, msg(id, 'inventory', 'Release', c.items));",
    "status = 'failed';",
  ],
  'cancelled-keeps-reservation': [
    "status = 'cancelled';\n            net = withSent(rest, msg(id, 'inventory', 'Release', c.items));",
    "status = 'cancelled';",
  ],
  'charge-while-declining': ['if (model.declining || model.charged', 'if (false || model.charged'],
  'cancel-while-paying': ["else if (c.status === 'paying') return reject('payment-in-progress');", "else if (c.status === 'paying') next.carts = setCart(model.carts, cart, { status: 'cancelled' });"],
};

mkdirSync(new URL('./out/', import.meta.url), { recursive: true });
let failed = false;
for (const [name, [from, to]] of Object.entries(MUTANTS)) {
  if (!source.includes(from)) throw new Error(`mutant ${name}: pattern not found`);
  const file = new URL(`./out/mutant-${name}.cjs`, import.meta.url);
  writeFileSync(file, source.replace(from, to));
  const res = check({ specModule: loadSpec(file.pathname.replace(/^\/([A-Za-z]:)/, '$1')), contract, invariants, maxStates: 100000 });
  const names = [...new Set((res.violations || []).map((v) => v.name || v.invariant))];
  console.log(`${name}: ${names.length ? 'caught by ' + names.join(', ') : 'NOT CAUGHT'}`);
  if (!names.length) failed = true;
}
process.exit(failed ? 1 : 0);

