'use strict';
// SAM v2 strict-profile specification of src/core.ts: three carts (a, b, c),
// the inventory, the payment service, and the messages in transit.
//
// The network is a multiset of messages, kept as a SORTED array of strings
// "from>to:Action:n" (n = qty or amount, 0 when the message has no number) so
// that two states differing only in send order are the same state. DELIVER
// {i} delivers the i-th message of that sorted list; any order of delivery is
// therefore explored. A cart not yet opened has status 'none'. A returned cart
// has two messages in flight (Refund, Release), so at most 6 are in transit.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CARTS = ['a', 'b', 'c'];
const INITIAL_STOCK = 2;
const MAX_ITEMS = 2;
const CHARGE_LIMIT = 4;
const PRICE = 1;

const INITIAL_STATE = {
  carts: {
    a: { status: 'none', items: 0 },
    b: { status: 'none', items: 0 },
    c: { status: 'none', items: 0 },
  },
  available: INITIAL_STOCK,
  reserved: 0,
  charged: 0,
  declining: false,
  net: [],
};

const msg = (from, to, action, n = 0) => `${from}>${to}:${action}:${n}`;
const parse = (m) => {
  const [route, action, n] = m.split(':');
  const [from, to] = route.split('>');
  return { from, to, action, n: Number(n) };
};
const withSent = (net, ...ms) => [...net, ...ms].sort();
const without = (net, i) => net.filter((_, j) => j !== i);
const setCart = (carts, id, patch) => ({ ...carts, [id]: { ...carts[id], ...patch } });

const cartDomain = CARTS.map((cart) => ({ cart }));
const cartSchema = { cart: { type: 'string', required: true } };
const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      carts: { type: 'object' },
      available: { type: 'number' },
      reserved: { type: 'number' },
      charged: { type: 'number' },
      declining: { type: 'boolean' },
      net: { type: 'array' },
    },
    actions: {
      OPEN: intent(cartSchema, cartDomain),
      ADD: intent(cartSchema, cartDomain),
      CHECKOUT: intent(cartSchema, cartDomain),
      CANCEL: intent(cartSchema, cartDomain),
      DECLINE: intent({}, [{}]),
      ACCEPT: intent({}, [{}]),
      RETURN: intent(cartSchema, cartDomain),
      DELIVER: intent({ i: { type: 'number', required: true } }, [0, 1, 2, 3, 4, 5].map((i) => ({ i }))),
    },
    acceptors: {
      OPEN: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c) return reject('unknown-cart-id');
        if (c.status !== 'none') return reject('cart-exists');
        next.carts = setCart(model.carts, cart, { status: 'open', items: 0 });
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      ADD: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status !== 'open') return reject('cart-not-open');
        if (c.items >= MAX_ITEMS) return reject('cart-full');
        next.carts = setCart(model.carts, cart, { items: c.items + 1 });
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      CHECKOUT: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status !== 'open') return reject('cart-not-open');
        if (c.items < 1) return reject('cart-empty');
        next.carts = setCart(model.carts, cart, { status: 'reserving' });
        next.net = withSent(model.net, msg(cart, 'inventory', 'Reserve', c.items));
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      CANCEL: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status === 'open') next.carts = setCart(model.carts, cart, { status: 'cancelled' });
        else if (c.status === 'reserving') next.carts = setCart(model.carts, cart, { status: 'cancelling' });
        else if (c.status === 'paying') return reject('payment-in-progress');
        else return reject('cart-not-cancellable');
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      RETURN: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status !== 'paid') return reject('cart-not-paid');
        next.carts = setCart(model.carts, cart, { status: 'returned' });
        next.net = withSent(model.net, msg(cart, 'payments', 'Refund', c.items * PRICE), msg(cart, 'inventory', 'Release', c.items));
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      DECLINE: (model) => (_p, { reject, next, unchanged }) => {
        if (model.declining) return reject('already-declining');
        next.declining = true;
        unchanged('carts', 'available', 'reserved', 'charged', 'net');
      },
      ACCEPT: (model) => (_p, { reject, next, unchanged }) => {
        if (!model.declining) return reject('already-accepting');
        next.declining = false;
        unchanged('carts', 'available', 'reserved', 'charged', 'net');
      },
      DELIVER: (model) => ({ i }, { reject, next, unchanged }) => {
        if (!(i >= 0 && i < model.net.length)) return reject('no-message-at-index');
        const m = parse(model.net[i]);
        const rest = without(model.net, i);

        if (m.to === 'inventory') {
          if (m.action === 'Reserve') {
            if (m.n <= model.available) {
              next.available = model.available - m.n;
              next.reserved = model.reserved + m.n;
              next.net = withSent(rest, msg('inventory', m.from, 'Reserved'));
            } else {
              next.net = withSent(rest, msg('inventory', m.from, 'OutOfStock'));
              unchanged('available', 'reserved');
            }
          } else { // Release
            next.available = model.available + m.n;
            next.reserved = model.reserved - m.n;
            next.net = rest;
          }
          unchanged('carts', 'charged', 'declining');
          return;
        }

        if (m.to === 'payments' && m.action === 'Refund') { // no answer
          next.charged = model.charged - m.n;
          next.net = rest;
          unchanged('carts', 'available', 'reserved', 'declining');
          return;
        }

        if (m.to === 'payments') { // Charge
          if (model.declining || model.charged + m.n > CHARGE_LIMIT) {
            next.net = withSent(rest, msg('payments', m.from, 'Declined'));
            unchanged('charged');
          } else {
            next.charged = model.charged + m.n;
            next.net = withSent(rest, msg('payments', m.from, 'Charged'));
