1	// The rules the brief requires, as predicates over spec/checkout.cjs states.
2	const STOCK = 2;
3	const LIMIT = 4;
4	
5	const parse = (m) => {
6	  const [route, action, n] = m.split(':');
7	  const [from, to] = route.split('>');
8	  return { from, to, action, n: Number(n) };
9	};
10	const msgs = (s) => s.net.map(parse);
11	const carts = (s) => Object.entries(s.carts);
12	const sum = (xs) => xs.reduce((a, b) => a + b, 0);
13	const inFlight = (s, pred) => msgs(s).some(pred);
14	
15	const paidUnits = (s) => sum(carts(s).filter(([, c]) => c.status === 'paid').map(([, c]) => c.items));
16	
17	// Units the inventory holds for a cart right now (reserved, not yet released).
18	const heldBy = (s, id, c) => {
19	  if (c.status === 'paying' || c.status === 'paid') return c.items;
20	  if ((c.status === 'reserving' || c.status === 'cancelling') &&
21	      inFlight(s, (m) => m.to === id && m.action === 'Reserved')) return c.items;
22	  return 0;
23	};
24	const releasing = (s) => sum(msgs(s).filter((m) => m.action === 'Release').map((m) => m.n));
25	const refunding = (s) => sum(msgs(s).filter((m) => m.action === 'Refund').map((m) => m.n));
26	
27	export const stateInvariants = [
28	  { name: 'stock-conserved', pred: (s) => s.available >= 0 && s.reserved >= 0 && s.available + s.reserved === STOCK },
29	  { name: 'reserved-accounted', pred: (s) => s.reserved === sum(carts(s).map(([id, c]) => heldBy(s, id, c))) + releasing(s) },
30	  {
31	    name: 'charged-accounted',
32	    pred: (s) => s.charged === paidUnits(s) + sum(carts(s)
33	      .filter(([id, c]) => c.status === 'paying' && inFlight(s, (m) => m.to === id && m.action === 'Charged'))
34	      .map(([, c]) => c.items)) + refunding(s),
35	  },
36	  { name: 'charged-nonnegative', pred: (s) => s.charged >= 0 },
37	  { name: 'quiescent-reserved-is-paid', pred: (s) => s.net.length > 0 || s.reserved === paidUnits(s) },
38	  { name: 'quiescent-charged-is-paid', pred: (s) => s.net.length > 0 || s.charged === paidUnits(s) },
39	  { name: 'charge-limit', pred: (s) => s.charged <= LIMIT },
40	  { name: 'items-bounded', pred: (s) => carts(s).every(([, c]) => c.items >= 0 && c.items <= 2) },
41	  { name: 'checked-out-carts-nonempty', pred: (s) => carts(s).every(([, c]) => ['none', 'open', 'cancelled'].includes(c.status) || c.items >= 1) },
42	  {
43	    name: 'one-message-per-cart',
44	    pred: (s) => carts(s).every(([id, c]) => msgs(s).filter((m) => m.from === id || m.to === id).length <= (c.status === 'returned' ? 2 : 1)),
45	  },
46	];
47	
48	const cartIds = (s) => Object.keys(s.carts);
49	const delivered = (pre, data) => (data && typeof data.i === 'number' ? parse(pre.net[data.i] ?? '?>?:?:0') : null);
50	
51	export const transitionInvariants = [
52	  {
53	    name: 'paid-only-after-reserve-and-charge',
54	    pred: (pre, action, data, post) => cartIds(post).every((id) => {
