          case 'cancelling/OutOfStock': status = 'cancelled'; break;
          case 'paying/Charged': status = 'paid'; break;
          case 'paying/Declined': status = 'declined'; break; // units stay reserved
          case 'abandoning/Charged':
            status = 'failed';
            net = withSent(rest, msg(id, 'payments', 'Refund', c.items * PRICE));
            break;
