// Capture real traces from src/core.ts for polygraph replay against
// spec/checkout.cjs. Each step drives the implementation, then projects its
// state onto the contract's observable keys. Run: node spec/capture.ts
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import * as core from '../src/core.ts';
import type { Message } from '../host.ts';

const CARTS = ['a', 'b', 'c'];
const DIR = new URL('./traces/', import.meta.url);

const encode = (m: Message): string => {
  const n = m.action === 'Reserve' || m.action === 'Release' ? m.data.qty
    : m.action === 'Charge' || m.action === 'Refund' ? m.data.amount : 0;
  return `${m.from}>${m.to}:${m.action}:${n}`;
};

function project(sys: core.System) {
  const carts: Record<string, { status: string; items: number }> = {};
  for (const id of CARTS) {
    const c = sys.carts.get(id);
    carts[id] = c ? { status: c.status, items: c.items } : { status: 'none', items: 0 };
  }
  return {
    carts,
    available: sys.inventory.available,
    reserved: sys.inventory.reserved,
    charged: sys.payments.charged,
    declining: sys.payments.declining,
    net: sys.inFlight.map(encode).sort(),
  };
}

type Step = { action: string; data: Record<string, unknown> };

function apply(sys: core.System, { action, data }: Step): void {
  const cart = data.cart as string;
  switch (action) {
    case 'OPEN': core.open(sys, cart); break;
    case 'ADD': core.add(sys, cart); break;
    case 'CHECKOUT': core.checkout(sys, cart); break;
    case 'CANCEL': core.cancel(sys, cart); break;
    case 'RETURN': core.returnCart(sys, cart); break;
    case 'RETRY': core.retry(sys, cart); break;
    case 'ABANDON': core.abandon(sys, cart); break;
    case 'DECLINE': core.declineCards(sys); break;
    case 'ACCEPT': core.acceptCards(sys); break;
    case 'DELIVER': {
      const sorted = sys.inFlight.map(encode).sort();
      const target = sorted[data.i as number];
      if (target === undefined) break;
      const m = sys.inFlight.find((x) => encode(x) === target)!;
      core.deliver(sys, m.id);
      break;
    }
  }
}

function run(name: string, steps: Step[]): void {
